#[cfg(not(feature = "private-leaf-salts"))]
pub const DOMAIN: &[u8] = b"aspis:r0:20261009:v1";
#[cfg(feature = "private-leaf-salts")]
pub const DOMAIN: &[u8] = b"UNPROVED:R1:PRIVATE-SALTED:SEMANTIC:P3";

/// Fresh R0 state, separate from Transcript's legacy all-zero IV. The
/// C1-time binding is exactly SPEC §9: public bytes and the C1 root in one
/// hash, with no profile/basis/nonce/registry pre-absorbs. Row 0 is empty.
#[derive(Clone)]
pub struct SemanticTranscript {
    state: [u8; 32],
    hash: HashFn,
    next_row: u8,
}

pub fn new(hash: HashFn, public_bytes: &[u8], c1_root: &[u8; 32]) -> Result<Self, Error> {
    let length = u32::try_from(public_bytes.len()).map_err(|_| Error::Public)?;
    Ok(Self {
        state: hash(&[DOMAIN, &[0], &length.to_le_bytes(), public_bytes, c1_root]),
        hash,
        next_row: 0,
    })
}
pub fn state(&self) -> [u8; 32] {
    self.state
}
pub fn next_row(&self) -> u8 {
    self.next_row
}

fn sample_block_validated(&mut self, row: u8, framed: &[u8]) -> Result<[u8; 32], Error> {
    if row != self.next_row {
        return Err(Error::RowOrder {
            expected: self.next_row,
            actual: row,
        });
    }
    // Exactly one absorb, one squeeze and one advance. Both reads
    // use s_abs; advancing from the challenge block would be wrong.
    let absorbed = (self.hash)(&[&self.state, &[0, 0xa0 + row], framed]);
    let block = (self.hash)(&[&absorbed, &[1]]);
    self.state = (self.hash)(&[&absorbed, &[2]]);
    self.next_row += 1;
    Ok(block)
}

pub(crate) fn semantic_validated(
    &mut self,
    record: ValidatedRecord<'_>,
) -> Result<QM31, Error> {
    let row = record.row();
    if row > 24 {
        return Err(Error::InvalidRow);
    }
    Ok(qm31_sample(
        &self.sample_block_validated(row, record.framed())?,
    ))
}

pub(crate) fn circle_validated(
    &mut self,
    record: ValidatedRecord<'_>,
) -> Result<SecureCirclePoint, Error> {
    let row = record.row();
    let circle_row = match row {
        25 => CircleRow::First,
        26 => CircleRow::Second,
        _ => return Err(Error::InvalidRow),
    };
    Ok(circle_sample(
        &self.sample_block_validated(row, record.framed())?,
        circle_row,
    ))
}

pub fn record(&self, row: u8) -> Result<&'a [u8], Error> {
    if row >= 27 {
        return Err(Error::InvalidRow);
    }
    Ok(self.records[row as usize])
}
pub fn payload(&self, row: u8) -> Result<&'a [u8], Error> {
    let framed = self.record(row)?;
    Ok(&framed[5..])
}
pub(crate) fn validated_record(&self, row: u8) -> Result<ValidatedRecord<'a>, Error> {
    Ok(ValidatedRecord {
        row,
        framed: self.record(row)?,
    })
}

pub fn begin(
    prefix: &Prefix<'_>,
    transcript: &mut SemanticTranscript,
) -> Result<Challenges, Error> {
    let lambda = transcript.semantic_validated(prefix.validated_record(0)?)?;
    let chi = transcript.semantic_validated(prefix.validated_record(1)?)?;
    let theta = transcript.semantic_validated(prefix.validated_record(2)?)?;
    let mut zc = [QM31::ZERO; 10];
    for (i, value) in zc.iter_mut().enumerate() {
        *value = transcript.semantic_validated(prefix.validated_record(3 + i as u8)?)?;
    }
    let mu = transcript.semantic_validated(prefix.validated_record(13)?)?;
    let eta = transcript.semantic_validated(prefix.validated_record(14)?)?;
    Ok(Challenges {
        lambda,
        chi,
        theta,
        zc,
        mu,
        eta,
    })
}

#[inline(never)]
pub fn verify_observed(public: Public<'_>, bytes: &[u8], hash: HashFn, obs: crate::verifier::Observer) -> Result<Verified, Error> {
    fn mark(obs: crate::verifier::Observer, i: u8) {
        #[cfg(feature="detail-phases")]
        if let Some(f)=obs {f(crate::verifier::Phase::SemanticPart(i));}
        #[cfg(not(feature="detail-phases"))]
        let _=(obs,i);
    }
    let prefix = Prefix::parse(bytes)?;
    mark(obs, 0);
    let mut transcript = SemanticTranscript::new(
        hash,
        &public.public_bytes().map_err(|_| Error::Public)?,
        prefix.c1_root,
    )?;
    let challenges = wire::begin(&prefix, &mut transcript)?;
    mark(obs, 1);
    let mut running = prefix.validated_record(14)?.decode_k::<1>(0)?[0];
    let mut alpha = [QM31::ZERO; 10];
    #[cfg(feature = "prover")]
    let mut round_checks = [[QM31::ZERO; 3]; 10];
    for round in 0..10 {
        let row = 15 + round as u8;
        let polynomial = prefix.validated_record(row)?.decode_k::<28>(0)?;
        let boundary = polynomial.iter().copied().fold(polynomial[0], QM31::add);
        if boundary != running {
            return Err(Error::Boundary { round });
        }
        alpha[round] = transcript.semantic_validated(prefix.validated_record(row)?)?;
        let value = polynomial
            .iter()
            .rev()
            .fold(QM31::ZERO, |a, &c| a.mul(alpha[round]).add(c));
        #[cfg(feature = "prover")]
        {
            round_checks[round] = [running, boundary, value];
        }
        running = value;
    }
    mark(obs, 2);
    let claims = claims(&prefix)?;
    let original_challenges = aspis_core::state_only_prefix::r0::Challenges {
        lambda: challenges.lambda,
        chi: challenges.chi,
        theta: challenges.theta,
        zc: challenges.zc,
        mu: challenges.mu,
        eta: challenges.eta,
    };
    let terminal = public
        .terminal_qm31(&claims, &alpha, &original_challenges)
        .map_err(|_| Error::Public)?;
    mark(obs, 3);
    let mask = aspis_core::state_only_hiding::state_only_selected_mask_value(
        &core::array::from_fn(|i| claims[0][i]),
        &core::array::from_fn(|i| claims[0][16 + i]),
        claims[0][27],
        &alpha,
    );
    let extra = prefix.validated_record(25)?.decode_k::<29>(87)?;
    let masked_terminal = mask.add(challenges.eta.mul(terminal)).add(extra[28]);
    if running != masked_terminal {
        return Err(Error::Terminal);
    }
    mark(obs, 4);
    let state_before_z0 = transcript.state();
    let z0 = transcript.circle_validated(prefix.validated_record(25)?)?;
    let before_z1 = prefix.validated_record(26)?.decode_k::<29>(0)?;
    let z1 = transcript.circle_validated(prefix.validated_record(26)?)?;
    mark(obs, 5);
    #[cfg(feature = "prover")]
    {
        for (i, x) in [z0.x, z0.y, z1.x, z1.y].into_iter().enumerate() {
            crate::trace::value(3, i, aspis_core::field::WideExact::from_qm31(x));
        }
        for (i, x) in challenges.with_alphas(&alpha).into_iter().enumerate() {
            crate::trace::value(0, i, x);
        }
        for (i, row) in round_checks.iter().enumerate() {
            for (j, x) in row.iter().enumerate() {
                crate::trace::value(1, 3 * i + j, aspis_core::field::WideExact::from_qm31(*x));
            }
        }
        crate::trace::value(2, 0, aspis_core::field::WideExact::from_qm31(terminal));
        crate::trace::value(
            2,
            1,
            aspis_core::field::WideExact::from_qm31(masked_terminal),
        );
    }
    if z0 == z1 {
        return Err(Error::EqualCirclePoints);
    }
    Ok(Verified {
        roots: [*prefix.c1_root, prefix.payload(2)?.try_into().unwrap()],
        challenges,
        alpha,
        claims,
        extra,
        before_z1,
        state_before_z0,
        z: [z0, z1],
        transcript,
        #[cfg(feature = "prover")]
        round_checks,
        #[cfg(feature = "prover")]
        terminal,
        #[cfg(feature = "prover")]
        masked_terminal,
    })
}

#[inline(never)]
fn claims(prefix: &Prefix<'_>) -> Result<Box<[[QM31; 29]; 3]>, Error> {
    let record = prefix.validated_record(25)?;
    let mut out =
        aspis_core::r0::heap::uninit::<[[QM31; 29]; 3]>().map_err(|_| Error::Allocation)?;
    unsafe {
        for p in 0..3 {
            out.as_mut_ptr()
                .cast::<[QM31; 29]>()
                .add(p)
                .write(record.decode_k::<29>(p * 29)?);
        }
        Ok(out.assume_init())
    }
}

#[derive(Debug,Clone,Copy,PartialEq,Eq)]
pub enum Error { Parse,Semantic,Transcript,Relation,Merkle,Query,Checkpoint,Allocation }
#[derive(Debug,Clone,Copy,PartialEq,Eq)]
pub enum Phase { Parsed,Semantic,SemanticPart(u8),Prepare,CheckpointRead,Merkle(usize),Query(usize),QueryPart(usize,u8),CheckpointWrite,Relation,Final }
pub type Observer=Option<fn(Phase)>;
fn mark(obs:Observer,p:Phase) { if let Some(f)=obs {f(p);} }

impl Prepared {
    #[inline(never)]
    pub fn new(sem:&crate::r1_semantic::Verified,v:&View<'_>,hash:HashFn)->Result<Box<Self>,Error> {
        let mut t=Transcript::new(hash,sem.transcript.state(),v.variant);
        let gamma=t.scalar(27,v.y1,true);
        let kappa=t.scalar(28,&v.inactive.to_le_bytes(),false);
        let mut alpha=[t.scalar(29,v.round0,false),E::ZERO];
        if v.variant.folds()==2 {
            let mut bytes=Vec::with_capacity(32+224);bytes.extend_from_slice(v.folded_root.unwrap());bytes.extend_from_slice(v.round1);
            alpha[1]=t.scalar(30,&bytes,false);
        }
        let row=if v.variant.folds()==1 {30}else{31};
        let queries=t.queries(row,v.final_message)?;
        let rho=t.scalar_k(row+1,&[]);
        let g=powers::<29>(gamma);let k=powers::<7>(kappa);
        let mut parts=[E::ZERO;7];parts[0]=v.inactive;
        for point in 0..6 {
            let mut dot=crate::fast_pairing::EbyKDot::new();
            for l in 0..29 {
                let scalar=match point {0..=2=>sem.claims[point][l],3=>sem.extra[l],4=>sem.before_z1[l],_=>field(v.y1,l).c0()};
                dot.push(g[l],scalar).map_err(|_|Error::Parse)?;
            }
            parts[point+1]=dot.finish();
        }
        let mut claim=E::ZERO;
        for i in 0..7 {crate::trace::value(14,i,parts[i]);claim=claim.add(k[i].mul(parts[i]));}
        crate::trace::value(14,7,claim);
        Ok(Box::new(Self{variant:v.variant,roots:sem.roots,gamma,kappa,alpha,rho,queries,semantic_alpha:sem.alpha,z:sem.z,claim,state:t.state}))
    }
}

#[inline(never)]
pub fn tx1(public:Public<'_>,public_bytes:&[u8],proof:&[u8],k:usize,hash:HashFn,obs:Observer)->Result<Vec<u8>,Error> {
    if k>22 {return Err(Error::Parse);}
    let v=View::parse(proof)?;mark(obs,Phase::Parsed);
    let sem=crate::r1_semantic::verify_observed(public,v.semantic,hash,obs).map_err(|_|Error::Semantic)?;mark(obs,Phase::Semantic);
    let p=Prepared::new(&sem,&v,hash)?;let mut a=Accumulator::new(v.variant)?;let g=powers::<29>(p.gamma);mark(obs,Phase::Prepare);
    let geometry=QueryGeometry::for_range(&p.queries,0,k)?;
    while a.next<k {query_with_geometry(&v,&p,&mut a,&g,hash,obs,&geometry)?;}
    let bytes=checkpoint(&p,&a,proof,public_bytes,hash);mark(obs,Phase::CheckpointWrite);Ok(bytes)
}

//! UNPROVED COST PROBE. Explicit opening schedule, including rho after queries.
use aspis_core::r0::CodeField;
use aspis_core::{HashFn,field::WideExact as E};
use crate::transport::Variant;
pub struct Transcript { pub state:[u8;32], hash:HashFn }
impl Transcript {
    pub fn new(hash:HashFn, semantic_state:[u8;32], variant:Variant) -> Self {
        #[cfg(not(feature = "private-leaf-salts"))]
        let domain: &[u8] = b"UNPROVED:R1:COST-PROBE:P2";
        #[cfg(feature = "private-leaf-salts")]
        let domain: &[u8] = b"UNPROVED:R1:PRIVATE-SALTED:P3";
        Self { state:hash(&[domain,&[variant.tag()],&semantic_state]), hash }
    }
    pub fn absorb(&mut self, row:u8, payload:&[u8]) {
        self.state=(self.hash)(&[&self.state,&[0,0xa0+row],&(payload.len() as u32).to_le_bytes(),payload]);
    }
    pub fn block(&mut self,row:u8,payload:&[u8])->[u8;32] {
        self.absorb(row,payload);
        let block=(self.hash)(&[&self.state,&[1]]);
        self.state=(self.hash)(&[&self.state,&[2]]);
        block
    }
    pub fn scalar(&mut self,row:u8,payload:&[u8],nonzero:bool)->E {
        let block=self.block(row,payload);
        let out=if nonzero {crate::sampler::gamma_sample(&block)} else {crate::sampler::ordinary_sample(&block)};
        crate::trace::value(4,row as usize,out); out
    }
    /// Final query-residual batching: at most 22 coefficients, so a nonzero
    /// residual has at most 21 roots even when sampled from the K subfield.
    /// Gamma and both folding challenges continue to use E.
    pub fn scalar_k(&mut self,row:u8,payload:&[u8])->aspis_core::field::QM31 {
        let out=crate::sampler::qm31_sample(&self.block(row,payload));
        crate::trace::value(4,row as usize,E::from_qm31(out)); out
    }
    pub fn queries(&mut self, row:u8, payload:&[u8])->Result<[u32;22],crate::verifier::Error> {
        self.absorb(row,payload);
        let mut blocks=[[0;32];8];let mut advances=blocks; let mut state=self.state;
        for k in 0..8 {
            blocks[k]=(self.hash)(&[&state,&[1]]);
            advances[k]=(self.hash)(&[&state,&[2]]);state=advances[k];
        }
        let (q,state)=aspis_core::r0_transcript::queries_from_pairs(&blocks,&advances).map_err(|_|crate::verifier::Error::Transcript)?;
        self.state=state;
        for (i,&u) in q.iter().enumerate() { crate::trace::value(5,i,E::from_m31(aspis_core::field::M31(u))); }
        Ok(q)
    }
}

/// SPEC §2 adapter for callers that materialize all eight squeeze/advance
/// pairs before scanning. Returns scanOut's selected state, which can precede
/// the eighth advance. The sampler and its stop test are shared with R-B.
pub fn queries_from_pairs(
    blocks: &[[u8; 32]; 8],
    advances: &[[u8; 32]; 8],
) -> Result<([u32; QUERY_COUNT], [u8; 32]), QuerySampleError> {
    let mut scan = QueryScan::default();
    let mut state = advances[7];
    for k in 0..8 {
        if scan.scan(&blocks[k]) {
            state = advances[k];
            break;
        }
    }
    Ok((scan.finish()?, state))
}

#[inline(never)]
fn mark(phase:Phase){
    match phase {
        Phase::QueryPart(i,j)=>msg!("r1:query-part:{}:{}",i,j),
        Phase::SemanticPart(i)=>msg!("r1:semantic-part:{}",i),
        Phase::Parsed=>msg!("r1:parsed"),Phase::Semantic=>msg!("r1:semantic"),Phase::Prepare=>msg!("r1:prepare"),
        Phase::CheckpointRead=>msg!("r1:checkpoint-read"),Phase::CheckpointWrite=>msg!("r1:checkpoint-write"),
        Phase::Merkle(i)=>msg!("r1:merkle:{}",i),Phase::Query(i)=>msg!("r1:query:{}",i),
        Phase::Relation=>msg!("r1:relation"),Phase::Final=>msg!("r1:final"),
    }
    sol_log_compute_units();
}
fn error(e:verifier::Error)->ProgramError{msg!("r1:error:{:?}",e);ProgramError::InvalidInstructionData}
#[inline(never)]
fn first(public_bytes:&[u8],proof:&[u8],k:usize)->Result<Vec<u8>,ProgramError>{
    let statement=decode_pool_v1_pair_forest_terminal_statement_v1(public_bytes).map_err(|_|ProgramError::InvalidAccountData)?;
    let public=match &statement{PoolV1PairForestTerminalStatementV1::PrivateTransfer{common,public}=>Public::Transfer(public,&common.lane_transition),PoolV1PairForestTerminalStatementV1::Withdrawal{common,public}=>Public::Withdrawal(public,&common.lane_transition)};
    verifier::tx1(public,public_bytes,proof,k,|p|hashv(p).to_bytes(),Some(mark)).map_err(error)
}
